class Solution {
    public int integerBreak(int n){
        int[] dp=new int[n+1];
        for(int value=2;value<=n;value++)for(int first=1;first<value;first++)dp[value]=Math.max(dp[value],first*Math.max(value-first,dp[value-first]));
        return dp[n];
    }
}

code.kotlin:
class Solution {
    fun integerBreak(n:Int):Int{
        val dp=IntArray(n+1);
        for(value in 2..n)for(first in 1 until value)dp[value]=maxOf(dp[value],first*maxOf(value-first,dp[value-first]));
        return dp[n]
    }
}

